L43_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> \236\185\168\236\139\157\236\178\180 \234\184\176\236\130\172\235\139\168\236\157\180\235\158\152\227\133\139\227\133\139 \235\176\169\236\134\161 \236\187\168\236\133\137 \235\143\140\236\149\152\235\131\144\234\181\172 \227\133\139\227\133\139\n<color=#ffd34c>\226\150\160\226\150\160</color> \236\167\132\236\167\128\237\149\152\234\178\140 \235\167\158\236\167\128 \236\149\138\236\157\140? \236\153\156 \237\149\152\237\149\132 \236\164\145\236\132\184 \234\184\176\236\130\172 \236\187\168\236\133\137\236\157\184 \234\177\180\235\141\176?\n<color=#ffd34c>\226\150\160 \226\150\160</color> \234\183\188\235\141\176 \236\185\168\236\139\157\236\178\180\235\138\148 \234\180\180\235\172\188 \234\176\153\236\157\128 \234\177\176 \236\149\132\235\139\136\236\149\188?\n<color=#ffd34c>\226\150\160\226\150\160</color> \234\179\160\236\139\172\235\143\132\236\151\144\235\138\148 \236\157\184\234\176\132\236\157\180\235\158\145 \235\152\145\234\176\153\236\157\180 \236\131\157\234\184\180 \236\185\168\236\139\157\236\178\180\235\143\132 \236\158\136\235\139\164\234\179\160 \237\149\168.\n<color=#ffd34c>\226\150\160\226\150\160</color> \234\183\184\235\158\152\236\132\156 \235\141\184\237\131\128 \236\132\184\235\184\144\236\157\180 \237\151\172\237\148\132 \235\149\140\235\166\176 \234\177\176\234\179\160 \227\133\139\227\133\139\227\133\139\227\133\139\227\133\139\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> \236\185\180\235\130\152\235\166\172\236\149\132! \235\152\144 \237\149\168\236\132\160\236\156\188\235\161\156 \235\147\164\236\157\180\235\176\155\236\149\132\236\132\156 \236\185\168\236\139\157\236\178\180\235\147\164 \235\139\164 \236\163\189\236\151\172\235\178\132\235\166\172\236\158\144!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> \236\157\180\237\132\176\235\139\136\236\155\128 \235\139\172\235\139\172\237\149\152\234\178\160\235\132\164 \227\133\139\227\133\139"
