L43_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> \228\190\181\233\163\159\228\189\147\233\168\142\229\163\171\229\155\163\239\189\151\239\189\151\227\130\179\227\131\179\227\130\187\227\131\151\227\131\136\227\130\132\227\129\176\239\189\151\239\189\151\n<color=#ffd34c>\226\150\160\226\150\160</color> \227\131\158\227\130\184\227\129\157\227\129\134\227\129\152\227\130\131\227\130\147\239\188\159\227\128\128\227\129\170\227\130\147\227\129\167\227\130\136\227\130\138\227\129\171\227\130\136\227\129\163\227\129\166\228\184\173\228\184\150\230\153\130\228\187\163\227\129\174\233\168\142\229\163\171\227\130\179\227\131\179\227\130\187\227\131\151\227\131\136\227\129\170\227\130\147\227\129\160\227\130\136\n<color=#ffd34c>\226\150\160 \226\150\160</color> \227\129\167\227\130\130\228\190\181\233\163\159\228\189\147\227\129\163\227\129\166\227\128\129\227\131\144\227\130\177\227\131\162\227\131\179\227\129\191\227\129\159\227\129\132\227\129\170\227\130\130\227\129\174\227\129\152\227\130\131\227\129\170\227\129\132\239\188\159\n<color=#ffd34c>\226\150\160\226\150\160</color> \233\171\152\230\183\177\229\186\166\227\129\171\227\129\175\228\186\186\233\150\147\227\129\157\227\129\163\227\129\143\227\130\138\227\129\174\228\190\181\233\163\159\228\189\147\227\130\130\227\129\132\227\130\139\227\130\147\227\129\160\227\129\163\227\129\166\227\129\149\227\128\130\n<color=#ffd34c>\226\150\160\226\150\160</color> \227\129\160\227\129\139\227\130\137\227\131\135\227\131\171\227\130\191\227\130\187\227\131\150\227\131\179\227\129\140\230\148\175\230\143\180\232\166\129\232\171\139\227\129\151\227\129\159\227\130\147\227\129\160\227\129\151\239\189\151\239\189\151\239\189\151\239\189\151\239\189\151\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> \227\130\171\227\131\138\227\131\170\227\130\162\239\188\129\227\128\128\227\129\190\227\129\159\232\137\166\232\136\185\227\129\167\231\170\129\233\128\178\227\129\151\227\129\166\228\190\181\233\163\159\228\189\147\227\130\146\229\133\168\233\131\168\230\174\186\227\129\151\227\129\161\227\130\131\227\129\138\227\129\134\239\188\129\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> \227\130\168\227\130\191\227\131\139\227\130\166\227\131\160\229\132\178\227\129\145\227\128\129\227\129\130\227\129\150\227\131\188\227\129\163\227\129\153\239\189\151\239\189\151"
L42_1.m_SubTitle_JPN = L43_1
L43_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> C.O. knights! LOL! That's insane!\n<color=#ffd34c>\226\150\160\226\150\160</color> But seriously, why are they so fixated with medieval knights anyway?\n<color=#ffd34c>\226\150\160 \226\150\160</color> Aren't C.O.s supposed to look like monsters or something?\n<color=#ffd34c>\226\150\160\226\150\160</color> I heard that there are C.O.s that look exactly like humans in the hyperdepths.\n<color=#ffd34c>\226\150\160\226\150\160</color> Is that why Delta Seven called for help? LOL!\n<color=#ffd34c>\226\150\160\226\150\160</color> Let's go, Canary! Kill those C.O.s by ramming them with your ship again!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> Sounds like that's a lot of Eternium, no? LOL!"
