L17_1 = "<color=#ffd34c>\226\150\160\226\150\160</color> \236\158\160\234\185\144, \235\132\183\237\138\156\235\184\140 \236\152\129\236\131\129\235\147\164 \235\179\180\235\139\136\234\185\140, \236\161\176\235\148\148\236\149\133 \235\130\152\236\157\180\236\184\160 \236\151\132\236\178\173 \236\132\188\235\141\176?\n<color=#ffd34c>\226\150\160\226\150\160</color> \236\131\164\235\160\136\236\157\180\235\147\156\236\151\144 \236\182\156\235\170\176\237\150\136\235\141\152 \236\130\172\236\177\132\236\151\133\236\158\144\235\158\145 \236\139\184\236\154\176\235\138\148 \236\152\129\236\131\129\235\143\132 \236\158\136\236\150\180.\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> \235\139\185\236\151\176\237\158\136 \236\161\176\236\158\145\236\157\180\234\178\160\236\167\128! \234\183\184\235\159\176 \236\139\157\236\156\188\235\161\156 \235\170\184\234\176\146 \235\182\136\235\166\172\235\138\148 \237\131\156\236\138\164\237\129\172\237\143\172\236\138\164\234\176\128 \236\150\188\235\167\136\235\130\152 \235\167\142\236\157\128\235\141\176."
L16_1.m_SubTitle_KOREA = L17_1
L16_1.m_fSubTitleTalkTime = 0
L17_1 = "<color=#ffd34c>\226\150\160\226\150\160</color> \229\190\133\227\129\166\227\130\136\227\128\129\227\131\141\227\131\131\227\131\136\227\131\129\227\131\165\227\131\188\227\131\150\230\152\160\229\131\143\232\166\139\227\129\166\227\129\191\227\129\159\227\130\137\227\128\129\227\130\190\227\131\135\227\130\163\227\130\162\227\131\131\227\130\175\227\131\138\227\130\164\227\131\132\227\130\129\227\129\163\227\129\161\227\130\131\229\188\183\227\129\132\227\129\158\239\188\159\n<color=#ffd34c>\226\150\160\226\150\160</color> \227\130\183\227\131\163\227\131\172\227\131\188\227\131\137\227\129\171\231\143\190\227\130\140\227\129\159\233\151\135\233\135\145\230\165\173\232\128\133\227\129\168\230\136\166\227\129\134\230\152\160\229\131\143\227\130\130\227\129\130\227\130\139\227\128\130\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> \230\141\143\233\128\160\227\129\171\230\177\186\227\129\190\227\129\163\227\129\166\227\130\139\227\129\160\227\130\141\239\188\129\227\128\128\227\129\157\227\130\147\227\129\170\233\162\168\227\129\171\227\130\174\227\131\163\227\131\169\228\184\138\227\129\146\227\130\139\227\130\191\227\130\185\227\130\175\227\131\149\227\130\169\227\131\188\227\130\185\227\129\163\227\129\166\229\177\177\227\129\187\227\129\169\227\129\132\227\130\139\227\130\147\227\129\160\227\130\136\239\188\159"
